      },
      "publisher": {
        "@type": "Organization",
        "name": "DSD Properties",
        "logo": {
          "@type": "ImageObject",
          "url": "https://dsdproperties.in/public/images/logo.png"
        }
      },
      "mainEntityOfPage": "https://dsdproperties.in/blog/dhara-80-krishi-bhumi-aawasiya-hindi-lucknow-2026",
      "image": "https://dsdproperties.in/public/images/blogs/dhara_80_krishi_bhumi_aawasiya_hindi_featured_banner.webp"
    },
    {
      "@type": "FAQPage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "Krishi bhumi ko aawasiya kaise kare UP mein?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "UP mein krishi bhumi ko aawasiya banane ke liye Dhara 80 (UP Revenue Code 2006) ke tahat aavedan karna hota hai. Nivesh Mitra portal par online application jama karein, khatauni-khasra-registry-Aadhaar upload karein, Lekhpal ka spot survey hoga, phir SDM circle rate ka 2% shulk lekar declaration jari karega. Puri prakriya 45 din mein puri honi chahiye."
          }
        },
        {
          "@type": "Question",
          "name": "Dhara 80 kya hai zameen mein?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Dhara 80 UP Revenue Code 2006 ka provision hai jo krishi bhumi ke upyog ko badalne ki kanooni anumati deta hai. Yani agar aapki zameen bhulekh mein agricultural darj hai aur aap us par makan, dukan, ya factory banana chahte hain, to pehle SDM se Dhara 80 ke tahat declaration lena anivarya hai."
          }
        },
        {
          "@type": "Question",
          "name": "Dhara 80 aur 143 mein kya antar hai?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Kanooni roop se dono ka kaam ek hai. Fark sirf yeh hai ki Dhara 143 purane UPZA & LR Act 1950 ke tahat aati thi, jo 2016 tak UP Revenue Code 2006 ki Dhara 80 se replace ho chuki hai. Aam bolchal mein log aaj bhi 143 bolte hain, lekin ab har naya aadesh Dhara 80 ke tahat hi jari hota hai. Purane 143 aadesh (2016 se pehle ke) aaj bhi valid hain."
          }
        },
        {
          "@type": "Question",
          "name": "Dhara 80 kitne din me hota hai?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "2026 ke Service Level Agreement ke anusar puri prakriya adhikatam 45 din mein puri honi chahiye. Digital platform ke karan kai zilon mein 15-30 din mein bhi aadesh mil raha hai. Agar 45 din mein SDM nirnay nahi leta, to Dhara 89 ke tahat automatic deemed approval ka pravdhan hai."
          }
        },
        {
          "@type": "Question",
          "name": "Dhara 80 kaise check kare?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "upbhulekh.gov.in par jaayein, khata sankhya ya khasra number daalkar khatauni nikalein. Agar land type field mein Gair-Krishi likha hai, to Dhara 80 ho chuki hai. Agar Krishi likha hai, to conversion nahi hui. Chal rahe application ka status Nivesh Mitra dashboard par bhi dekha ja sakta hai."
          }
        },
        {
          "@type": "Question",
          "name": "143 land conversion charges UP mein kitne hain?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "UP mein land conversion charges ek hi hain — circle rate ka 2%. Udaharan: agar circle rate Rs 500 prati varg foot hai aur plot 1000 varg foot ka hai, to shulk hoga 2% × Rs 5,00,000 = Rs 10,000. Yeh rashi sarkari treasury mein e-Treasury challan ke madhyam se online jama hoti hai."
          }
        },
        {
          "@type": "Question",
          "name": "Kya Dhara 80 ke bina plot khareed sakte hain?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Haan, agricultural land par registry technically ho sakti hai, lekin kanooni roop se us par residential nirman nahi kiya ja sakta. Bank loan nahi dega, naksha approve nahi hoga, aur LDA kabhi bhi demolition action le sakti hai. Salah yahi hai ki Dhara 80 ho chuki zameen khareedein."
          }
        },
        {
          "@type": "Question",
          "name": "Kya LDA-approved colony mein alag se Dhara 80 karwani padti hai?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Nahi. 24 March 2026 ke UP cabinet ordinance ke baad, LDA ya UPAVP dwara approved colony mein jahan building plan swikrit hai, wahan Dhara 80 deemed approved maani jati hai. Lekin yeh chhoot sirf notified urban zones ke liye hai. Gaon, zila panchayat kshetra, ya non-approved private colony mein abhi bhi anivarya hai."
          }
        },
        {
          "@type": "Question",
          "name": "SC/ST zameen par Dhara 80 ke baad transfer par rok khatam ho jati hai?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Nahi. Dhara 80 keval zameen ke upyog ko krishi se gair-krishi mein badalti hai. Lekin UPZA & LR Act ki Dhara 98/99 ke tahat SC/ST zameen ko non-SC/ST ko bechne par lagi rok Dhara 80 ke baad bhi jari rehti hai. Aisi zameen bechne ke liye District Magistrate ki alag permission leni padti hai."
          }
        },
        {
          "@type": "Question",
          "name": "Kya purane Dhara 143 ke aadesh aaj bhi manya hain?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Haan, puri tarah manya. Agar kisi zameen par 2016 se pehle Dhara 143 ke tahat aadesh jari ho chuka hai, to woh aaj bhi legally valid hai. Dobara Dhara 80 ke tahat aadesh lene ki zaroorat nahi. Bas yeh sunischit kar lein ki khatauni mein land type Gair-Krishi dikh raha ho."
          }
        }
      ]
    }
  ]
